function checks(){
  const it=[];
  form.querySelectorAll('[required]:not(:disabled)').forEach(el=>{
    let ok=el.type==='checkbox'?el.checked:el.value.trim()!=='';
    if(ok&&el.dataset.pattern)ok=new RegExp(el.dataset.pattern).test(el.value.trim());
    if(ok&&el.type==='email')ok=/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(el.value.trim());
    it.push({el,ok,sec:el.closest('fieldset').id||'sx'});
  });
  it.push({el:$('#t_sales tr input'),ok:rows('sales').some(r=>r.brand&&!digitsOnly(r.brand)),sec:'s1'});
  it.push({el:$('#t_comp tr input'),ok:rows('comp').some(r=>r.name&&!digitsOnly(r.name)),sec:'s2'});
  $$('#t_sales input[data-f=brand],#t_comp input[data-f=name],#t_mkt input[data-f=city],#c_city,#c_name').forEach(el=>{if(digitsOnly(el.value))it.push({el,ok:false,sec:el.closest('fieldset').id})});
  REPS.center.ids.forEach(id=>{const el=$('#t_email'+sfx(id)),v=el?el.value.trim():'';if(v&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v))it.push({el,ok:false,sec:'s3'})});
  eqIds().forEach(id=>{const s=sfx(id);it.push({el:$(`.drop[data-photo="showroom${s}"]`),ok:(PHOTOS['showroom'+s]||[]).length>0,sec:'s4'})});   // хотя бы одно фото центра
  it.push({el:$('#regMap'),ok:REG.size>0,sec:'sr',drop:true});
  const planTot=orderTotals();
  it.push({el:$('.order-wrap'),ok:planTot>0,sec:'s7',drop:true});
  const ar=(form.querySelector('input[name=adv_ready]:checked')||{}).value||'', yes=ar==='Да'||ar==='Да, частично';
  it.push({el:$('#advReadyF'),ok:!!ar,sec:'s7',drop:true});
  const q=$('#adv_qty').value.trim(), qn=Number(q);
  if(yes){
  it.push({el:$('#adv_qty'),ok:q!==''&&Number.isInteger(qn)&&qn>0&&qn<=planTot,sec:'s7'});const pv=$('#adv_pct').value.trim(),pn=Number(pv);it.push({el:$('#adv_pct'),ok:pv!==''&&pn>=1&&pn<=100,sec:'s7'})}
    return it;
}
const digitsOnly=v=>{v=String(v||'').trim();return v!==''&&/^[\d\s.,+\-\/№#]+$/.test(v)};
function markDigits(){
  REPS.center.ids.forEach(id=>{const x=sfx(id),el=$('#t_email'+x),m=$('#t_email_err'+x);if(!el||!m)return;const v=el.value.trim(),bad=!!v&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v);m.hidden=!bad;el.classList.toggle('invalid',bad)});
  [['#t_sales input[data-f=brand]','#dg_sales'],['#t_comp input[data-f=name]','#dg_comp'],['#t_mkt input[data-f=city]','#dg_mkt'],['#c_city','#dg_city'],['#c_name','#dg_name']].forEach(([sel,m])=>{
    let bad=0;$$(sel).forEach(el=>{const b=digitsOnly(el.value);el.classList.toggle('invalid',b);el.setAttribute('aria-invalid',b?'true':'false');if(b)bad++});
    $(m).hidden=!bad;
  });
}
form.addEventListener('change',e=>{const t=e.target;if(t.classList&&t.classList.contains('xr')&&t.checked){$$(`input.xr[name="${t.name}"]`).forEach(o=>{if(o!==t)o.checked=false});progress()}});
function advUI(){
  const ar=(form.querySelector('input[name=adv_ready]:checked')||{}).value||'', yes=ar==='Да'||ar==='Да, частично';
  $('#advPctF').hidden=!yes;$('#advQtyF').hidden=!yes;
  const tot=OROWS.reduce((s,r)=>s+MONTHS.reduce((a,m,j)=>a+Math.max(0,parseInt($('#'+r.id+'_'+j).value)||0),0),0);
  const q=$('#adv_qty').value.trim(),qn=Number(q);
  const h=$('#advQtyHint');
  if(q!==''&&qn>tot){h.textContent=`Не больше, чем в плане продаж: ${tot} шт.`;h.style.color='var(--err)'}
  else if(yes&&q===''){h.textContent=`Укажите количество, из ${tot} шт. по плану.`;h.style.color=''}
  else {h.textContent=`Из ${tot} шт. по плану продаж.`;h.style.color=''}
}
function progress(){
  markDigits();advUI();
  const it=checks(), ok=it.filter(x=>x.ok).length;
  const req=$$('.rail a[data-req]'), miss=req.filter(a=>it.some(x=>x.sec===a.dataset.s&&!x.ok));
  $('#bar').style.width=((req.length-miss.length)/req.length*100)+'%';
  $('#pct').textContent=`Обязательные блоки: ${req.length-miss.length} из ${req.length}`;
  const m=$('#missing');
  if(miss.length){m.innerHTML='<b>Не заполнено:</b>'+miss.map(a=>`<a href="#${a.dataset.s}">${esc(a.querySelector('.nm').firstChild.textContent)}</a>`).join('');m.classList.remove('ok')}
  else{m.textContent='Все обязательные блоки заполнены';m.classList.add('ok')}
  const mn=$('#mNext');mn.hidden=false;
  if(miss.length){mn.classList.remove('ok');mn.href='#'+miss[0].dataset.s;mn.textContent='Заполнить: '+miss[0].querySelector('.nm').firstChild.textContent.replace(/^\d+\.\s*/,'')+' ›'}
  else{mn.classList.add('ok');mn.href='#go';mn.textContent='Готово к отправке ✓'}
  const opt={s2:()=>rows('comp').length>0,s3:()=>REPS.center.ids.some(id=>{const s=sfx(id);return !!($('#t_addr'+s).value.trim()||(!isOffice(id)&&((PHOTOS['siteMap'+s]||[]).length||(PHOTOS['facade'+s]||[]).length)))}),s4:()=>!eqIds().length||eqIds().some(id=>{const s=sfx(id);return !!($('#h_area'+s).value||(PHOTOS['showroom'+s]||[]).length)}),s5:()=>rows('mkt').length>0,s6:()=>rows('cli').length>0,s7:()=>orderTotals()>0};
  $$('.rail a[data-s]').forEach(a=>{
    const s=a.dataset.s, mine=it.filter(x=>x.sec===s), st=a.querySelector('.st');
    let done, txt;
    if(mine.length){const d=mine.filter(x=>x.ok).length;done=d===mine.length;txt=done?'✓':`${d}/${mine.length}`}
    else{done=opt[s]?opt[s]():false;txt=done?'✓':''}
    a.classList.toggle('done',done); a.classList.toggle('todo',!!a.dataset.req&&!done); st.textContent=txt;
  });
  orderTotals();
}
