let files={};
const safe=s=>(s||'кандидат').replace(/[\\/:*?"<>|«»]+/g,'').replace(/\s+/g,' ').trim().slice(0,60);
$$('.cl .v[data-copy]').forEach(btn=>btn.onclick=()=>{const t=btn.dataset.copy,msg=btn.parentElement.querySelector('.done'),say=m=>{msg.textContent=m;clearTimeout(btn._t);btn._t=setTimeout(()=>msg.textContent='',2000)};
  const sel=()=>{const r=document.createRange();r.selectNodeContents(btn);const s=getSelection();s.removeAllRanges();s.addRange(r);say('Выделено — нажмите Ctrl+C')};
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(()=>say('Скопировано'),sel);else sel()});
function toast(m,bad){const t=$('#toast');t.textContent=m;t.classList.toggle('bad',!!bad)}
const MIME={pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',pdf:'application/pdf',zip:'application/zip'};
function download(blob,name){
  const url=URL.createObjectURL(new Blob([blob],{type:MIME[name.split('.').pop()]||'application/octet-stream'})),a=document.createElement('a');
  a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
function save(kind){
  const f=files[kind]; if(!f){toast('Файл не собран. Попробуйте сформировать файлы еще раз.',true);return}
  try{download(f.blob,f.name);toast('Файл скачан: '+f.name+'. Он в папке «Загрузки».')}
  catch(e){toast('Не удалось скачать файл. Попробуйте скачать архив.',true)}
}
/* all files in one .zip */
async function saveZip(){
  const list=['pptx','planp'].map(k=>files[k]).filter(Boolean);
  if(!list.length){toast('Файлы не собраны. Попробуйте сформировать файлы еще раз.',true);return}
  try{const z={};for(const f of list)z[f.name]=new Uint8Array(await f.blob.arrayBuffer());
    const name=`Заявка дилера — ${safe($('#c_name').value)}.zip`;download(BAZFill.zip(z),name);
    toast('Архив скачан: '+name+'. Он в папке «Загрузки».')}
  catch(e){console.error(e);toast('Не удалось собрать архив. Скачайте файлы по одному.',true)}
}
$('#dlP').onclick=()=>save('pptx');$('#dlPP').onclick=()=>save('planp');$('#dlZip').onclick=saveZip;
